ank', 4),\n    pack('Metric', 'Private endpoint configured', 'Value', WithPrivateEndpoint, 'Rank', 5),\n    pack('Metric', 'Network ACLs allow all',      'Value', AclAllowAll,         'Rank', 6),\n    pack('Metric', 'Egress unrestricted',         'Value', EgressOpen,          'Rank', 7),\n    pack('Metric', 'No Key Vault or CMK',         'Value', NoKeyVault,          'Rank', 8))\n| mv-expand Tiles\n| project Metric = tostring(Tiles.Metric), Value = toint(Tiles.Value), Rank = toint(Tiles.Rank)\n| order by Rank asc",
