 == 1, 'High', RiskRank == 2, 'Medium', 'Healthy'),\n    Type = ResourceKind,\n    Region = location,\n    ['Managed identity'] = iff(isempty(IdentityType) or IdentityType =~ 'None', 'None', IdentityType),\n    ['User-assigned count'] = coalesce(UserAssignedCount, 0),\n    ['Identity principal ID'] = iff(isempty(PrincipalId), '-', PrincipalId),\n    ['API key auth'] = case(isnull(LocalAuthDisabled), 'Unknown', LocalAuthDisabled == true, 'Disabled (Entra ID only)', 'Enabled - keys usable'),\n    ['Key Vault / CMK'] = iff(isempty(KeyVaultUri), 'Microsoft-managed key', KeyVaultUri),\n    ['Encryption source'] = iff(isempty(CmkSource), 'Microsoft-managed', CmkSource),\n    ['Custom subdomain'] = iff(isempty(Subdomain), 'Not set', Subdomain),\n    Findings = iff(array_length(Findings) == 0, 'No findings', strcat_array(Findings, ' | ')),\n    RiskRank,\n    ResourceId = id\n| order by RiskRank asc, Resource asc\n| project-away RiskRank",
