 ['Resource group'] = resourceGroup,\n    Risk = case(RiskRank == 0, 'Critical', RiskRank == 1, 'High', RiskRank == 2, 'Medium', 'Healthy'),\n    Exposure,\n    Type = ResourceKind,\n    Region = location,\n    ['Public network access'] = iff(isempty(Pna), 'Unknown', Pna),\n    ['Network default action'] = iff(isempty(NetDefault), 'Allow (not configured)', NetDefault),\n    ['IP rules'] = IpRuleCount,\n    ['VNet rules'] = VnetRuleCount,\n    ['Private endpoints'] = PeCount,\n    ['Managed VNet isolation'] = iff(isempty(Isolation), 'Not configured', Isolation),\n    RiskRank,\n    ResourceId = id\n| order by RiskRank asc, ['Private endpoints'] asc, Resource asc\n| project-away RiskRank",
