resourceGroup,\n    Risk = case(RiskRank == 0, 'High', RiskRank == 1, 'Medium', 'Healthy'),\n    ['Egress control'] = EgressControl,\n    Type = ResourceKind,\n    Region = location,\n    ['Outbound restricted'] = case(isnull(RestrictOutbound), 'Not configured', RestrictOutbound == true, 'Yes', 'No'),\n    ['Allowed FQDN count'] = AllowedFqdnCount,\n    ['Managed VNet isolation'] = iff(isempty(Isolation), 'Not configured', Isolation),\n    ['Managed outbound rules'] = OutboundRuleCount,\n    ['VNet injections'] = InjectionCount,\n    RiskRank,\n    ResourceId = id\n| order by RiskRank asc, Resource asc\n| project-away RiskRank",
