  ['AI resource'] = AiResource,\n    Subscription = AiSubscription,\n    ['Resource group'] = AiResourceGroup,\n    Risk = case(RiskRank == 0, 'High - connection not approved', RiskRank == 1, 'Medium - public access still enabled', 'Healthy'),\n    ['Private endpoint'] = PeName,\n    ['Connection state'] = iff(isempty(ConnectionState), 'Unknown', ConnectionState),\n    ['Sub-resource'] = iff(isempty(GroupIds), '-', GroupIds),\n    Type = AiType,\n    ['Public access enabled'] = iff(AiPna =~ 'Enabled', 'Yes', 'No'),\n    Subnet = iff(isempty(SubnetId), '-', tostring(split(SubnetId, '/')[-1])),\n    ['Endpoint resource group'] = PeResourceGroup,\n    Region = PeLocation,\n    RiskRank,\n    ResourceId = PeId\n| order by RiskRank asc, ['AI resource'] asc\n| project-away RiskRank",
