          {
            "type": 1,
            "content": {
              "json": "## AI costs and token usage\r\n\r\nChoose the cost scope and select **Load cost data**. Use report, resource and billing-meter filters after loading."
            },
            "name": "cost-head"
          },
          {
            "type": 9,
            "name": "cost-scope-parameters",
            "content": {
              "version": "KqlParameterItem/1.0",
              "style": "pills",
              "parameters": [
                {
                  "id": "cost-sub",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostSubscription",
                  "label": "Cost subscription",
                  "type": 2,
                  "isRequired": true,
                  "multiSelect": false,
                  "quote": "",
                  "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| order by name asc\n| extend n = row_number()\n| project value = subscriptionId, label = name, selected = (n == 1)",
                  "queryType": 1,
                  "resourceType": "microsoft.resourcegraph/resources",
                  "crossComponentResources": [
                    "{Subscriptions}"
                  ],
                  "typeSettings": {
                    "showDefault": false,
                    "additionalResourceOptions": []
                  },
                  "description": "One subscription from the global selection. Cost Management is queried once per report, not once per estate subscription."
                },
                {
                  "id": "cost-time",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostTimeRange",
                  "label": "Date range",
                  "type": 4,
                  "isRequired": true,
                  "typeSettings": {
                    "selectableValues": [
                      {
                        "durationMs": 86400000
                      },
                      {
                        "durationMs": 604800000
                      },
                      {
                        "durationMs": 2592000000
                      },
                      {
                        "durationMs": 7776000000
                      }
                    ],
                    "allowCustom": true
                  },
                  "value": {
                    "durationMs": 2592000000
                  },
                  "description": "Preset or custom dates. Costs use UTC billing days; token metrics use the exact timestamps."
                },
                {
                  "id": "cost-basis",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostBasis",
                  "label": "Cost basis",
                  "type": 2,
                  "isRequired": true,
                  "quote": "",
                  "jsonData": "[{\"value\":\"ActualCost\",\"label\":\"Actual cost\"},{\"value\":\"AmortizedCost\",\"label\":\"Amortized cost\"}]",
                  "value": "ActualCost",
                  "typeSettings": {
                    "showDefault": false,
                    "additionalResourceOptions": []
                  }
                },
                {
                  "id": "cost-resource",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostResource",
                  "label": "AI resources",
                  "type": 2,
                  "isRequired": true,
                  "multiSelect": true,
                  "quote": "'",
                  "delimiter": ",",
                  "query": "resources\n| where subscriptionId == '{CostSubscription}'\n| where type in~ ('microsoft.cognitiveservices/accounts', 'microsoft.machinelearningservices/workspaces', 'microsoft.search/searchservices')\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| order by name asc\n| project value = tolower(id), label = strcat(name, ' [', resourceGroup, ']'), selected = false",
                  "queryType": 1,
                  "resourceType": "microsoft.resourcegraph/resources",
                  "crossComponentResources": [
                    "{Subscriptions}"
                  ],
                  "typeSettings": {
                    "selectAllValue": "*",
                    "showDefault": false,
                    "additionalResourceOptions": [
                      "value::all"
                    ]
                  },
                  "value": [
                    "value::all"
                  ],
                  "description": "Choose All or multiple AI resources within the selected cost subscription. The resource filter applies to every billing report and the meter picker. Token usage requires exactly one model-hosting account."
                },
                {
                  "id": "cost-meter-context",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostMeterContext",
                  "type": 1,
                  "isHiddenWhenLocked": true,
                  "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| where subscriptionId == '{CostSubscription}'\n| summarize SubscriptionCount = count()\n| extend JoinKey = 1\n| join kind=leftouter (\n    resources\n    | where subscriptionId == '{CostSubscription}'\n    | where type in~ ('microsoft.cognitiveservices/accounts', 'microsoft.machinelearningservices/workspaces', 'microsoft.search/searchservices')\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | where id in~ (dynamic([{CostResource}]))\n    | summarize ResourceCount = count(), ResourceKind = take_any(kind), ResourceType = take_any(type),\n        ResourceName = take_any(name), ResourceGroup = take_any(resourceGroup), ResourceRegion = take_any(location)\n    | extend JoinKey = 1\n) on JoinKey\n| extend Start = todatetime('{CostTimeRange:startISO}'), End = todatetime('{CostTimeRange:endISO}'),\n    Groups = dynamic([{ResourceGroups}]), SelectedResources = dynamic([{CostResource}]),\n    Basis = '{CostBasis}'\n| extend AllResources = array_length(SelectedResources) == 1 and set_has_element(SelectedResources, '*')\n| extend Status = case(\n    SubscriptionCount != 1, 'Select a cost subscription within the global subscription selection.',\n    array_length(SelectedResources) == 0 or set_has_element(SelectedResources, ''), 'Select All or one or more AI resources.',\n    not(AllResources) and set_has_element(SelectedResources, '*'), 'Select either All or specific AI resources, not both.',\n    not(AllResources) and ResourceCount != array_length(SelectedResources),\n        'One or more selected AI resources are outside the current subscription or resource-group scope. Reselect the AI resources or choose All.',\n    isnull(Start) or isnull(End) or End <= Start, 'Choose a valid, non-empty date range.',\n    End > now() + 5m, 'Choose a date range ending no later than now.',\n    End - Start > 365d, 'Cost reports support up to 365 days. Choose a shorter date range.',\n    Basis !in ('ActualCost', 'AmortizedCost'), 'Choose Actual cost or Amortized cost.',\n    'ready')\n| extend Filter = pack('dimensions', pack('name', 'ResourceType', 'operator', 'In',\n    'values', dynamic(['microsoft.cognitiveservices/accounts', 'microsoft.machinelearningservices/workspaces', 'microsoft.search/searchservices'])))\n| extend Filter = iff(array_length(Groups) == 0 or set_has_element(Groups, '*'),\n    Filter, pack('and', pack_array(Filter, pack('dimensions', pack('name', 'ResourceGroupName', 'operator', 'In', 'values', Groups)))))\n| extend Filter = iff(AllResources, Filter,\n    pack('and', pack_array(Filter, pack('dimensions', pack('name', 'ResourceId', 'operator', 'In', 'values', SelectedResources)))))\n| extend MeterBody = pack('type', Basis, 'timeframe', 'Custom',\n    'timePeriod', pack('from', '{CostTimeRange:startISO}', 'to', '{CostTimeRange:endISO}'),\n    'dataset', pack('granularity', 'None',\n        'aggregation', pack('totalCost', pack('name', 'Cost', 'function', 'Sum')),\n        'grouping', pack_array(pack('type', 'Dimension', 'name', 'Meter')),\n        'filter', Filter,\n        'sorting', pack_array(pack('direction', 'Descending', 'name', 'Cost'))))\n| project value = tostring(pack('status', Status, 'meterBody', tostring(MeterBody))), selected = true",
                  "queryType": 1,
                  "resourceType": "microsoft.resourcegraph/resources",
                  "crossComponentResources": [
                    "{Subscriptions}"
                  ]
                },
                {
                  "id": "cost-scope-status",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostScopeStatus",
                  "type": 1,
                  "isHiddenWhenLocked": true,
                  "criteriaData": [
                    {
                      "criteriaContext": {
