                        "operator": "Default",
                        "resultValType": "static"
                      }
                    }
                  ]
                },
                {
                  "id": "cost-loaded-scope",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostLoadedScope",
                  "type": 1,
                  "value": "",
                  "isGlobal": true,
                  "isHiddenWhenLocked": true
                },
                {
                  "id": "cost-scope-ready",
                  "version": "KqlParameterItem/1.0",
                  "name": "CostScopeReady",
                  "type": 1,
                  "isHiddenWhenLocked": true,
                  "criteriaData": [
                    {
                      "criteriaContext": {
                        "resultVal": "pending",
                        "operator": "is Empty",
                        "leftOperand": "CostLoadedScope",
                        "resultValType": "static"
                      }
                    },
                    {
                      "criteriaContext": {
                        "rightVal": "CostScopeKey",
                        "operator": "==",
                        "resultValType": "static",
                        "resultVal": "ready",
                        "leftOperand": "CostLoadedScope",
                        "rightValType": "param"
                      }
                    },
                    {
                      "criteriaContext": {
                        "resultVal": "pending",
                        "operator": "Default",
                        "resultValType": "static"
                      }
                    }
                  ]
                }
              ]
            }
          },
          {
