                        "id": "cost-context",
                        "version": "KqlParameterItem/1.0",
                        "name": "CostContext",
                        "type": 1,
                        "isHiddenWhenLocked": true,
                        "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| where subscriptionId == '{CostSubscription}'\n| summarize SubscriptionCount = count()\n| extend JoinKey = 1\n| join kind=leftouter (\n    resources\n    | where subscriptionId == '{CostSubscription}'\n    | where type in~ ('microsoft.cognitiveservices/accounts', 'microsoft.machinelearningservices/workspaces', 'microsoft.search/searchservices')\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | where id in~ (dynamic([{CostResource}]))\n    | summarize ResourceCount = count(), ResourceKind = take_any(kind), ResourceType = take_any(type),\n        ResourceName = take_any(name), ResourceGroup = take_any(resourceGroup), ResourceRegion = take_any(location)\n    | extend JoinKey = 1\n) on JoinKey\n| extend Start = todatetime('{CostTimeRange:startISO}'), End = todatetime('{CostTimeRange:endISO}'),\n    Groups = dynamic([{ResourceGroups}]), SelectedResources = dynamic([{CostResource}]),\n    Basis = '{CostBasis}'\n| extend AllResources = array_length(SelectedResources) == 1 and set_has_element(SelectedResources, '*')\n| extend Status = case(\n    SubscriptionCount != 1, 'Select a cost subscription within the global subscription selection.',\n    array_length(SelectedResources) == 0 or set_has_element(SelectedResources, ''), 'Select All or one or more AI resources.',\n    not(AllResources) and set_has_element(SelectedResources, '*'), 'Select either All or specific AI resources, not both.',\n    not(AllResources) and ResourceCount != array_length(SelectedResources),\n        'One or more selected AI resources are outside the current subscription or resource-group scope. Reselect the AI resources or choose All.',\n    isnull(Start) or isnull(End) or End <= Start, 'Choose a valid, non-empty date range.',\n    End > now() + 5m, 'Choose a date range ending no later than now.',\n    End - Start > 365d, 'Cost reports support up to 365 days. Choose a shorter date range.',\n    Basis !in ('ActualCost', 'AmortizedCost'), 'Choose Actual cost or Amortized cost.',\n    'ready')\n| extend Filter = pack('dimensions', pack('name', 'ResourceType', 'operator', 'In',\n    'values', dynamic(['microsoft.cognitiveservices/accounts', 'microsoft.machinelearningservices/workspaces', 'microsoft.search/searchservices'])))\n| extend Filter = iff(array_length(Groups) == 0 or set_has_element(Groups, '*'),\n    Filter, pack('and', pack_array(Filter, pack('dimensions', pack('name', 'ResourceGroupName', 'operator', 'In', 'values', Groups)))))\n| extend Filter = iff(AllResources, Filter,\n    pack('and', pack_array(Filter, pack('dimensions', pack('name', 'ResourceId', 'operator', 'In', 'values', SelectedResources)))))\n| extend Meters = dynamic([{CostMeters}]), Report = '{CostReport}'\n| extend Status = case(\n    Status != 'ready', Status,\n    Report in ('daily', 'dailymeters', 'dailyresourcemeters') and End - Start > 31d, 'The daily cost report supports up to 31 days. Shorten the range or select another report.',\n    Report !in ('summary', 'resources', 'meters', 'daily', 'dailymeters', 'resourcemeters', 'dailyresourcemeters', 'tokens'), 'Choose a cost report.',\n    Report != 'tokens' and not(set_has_element(Meters, '*')) and set_has_element(Meters, ''),\n        'The billing meter selection contains a blank value. Refresh the meter picker and select All or a named meter.',\n    'ready')\n| extend Filter = iff(array_length(Meters) == 0 or set_has_element(Meters, '*'), Filter,\n    pack('and', pack_array(Filter, pack('dimensions', pack('name', 'Meter', 'operator', 'In', 'values', Meters)))))\n| extend Grouping = case(\n    Report == 'resources', pack_array(pack('type', 'Dimension', 'name', 'ResourceId'), pack('type', 'Dimension', 'name', 'ServiceName')),\n    Report in ('resourcemeters', 'dailyresourcemeters'), pack_array(pack('type', 'Dimension', 'name', 'ResourceId'), pack('type', 'Dimension', 'name', 'Meter')),\n    Report in ('meters', 'dailymeters'), pack_array(pack('type', 'Dimension', 'name', 'Meter'), pack('type', 'Dimension', 'name', 'MeterSubCategory')),\n    pack_array(pack('type', 'Dimension', 'name', 'ServiceName')))\n| extend Aggregation = iff(Report in ('meters', 'resourcemeters', 'dailyresourcemeters'),\n    pack('totalCost', pack('name', 'Cost', 'function', 'Sum'), 'totalQuantity', pack('name', 'UsageQuantity', 'function', 'Sum')),\n    pack('totalCost', pack('name', 'Cost', 'function', 'Sum')))\n| extend Body = pack('type', Basis, 'timeframe', 'Custom',\n    'timePeriod', pack('from', '{CostTimeRange:startISO}', 'to', '{CostTimeRange:endISO}'),\n    'dataset', pack('granularity', iff(Report in ('daily', 'dailymeters', 'dailyresourcemeters'), 'Daily', 'None'), 'aggregation', Aggregation,\n        'grouping', Grouping, 'filter', Filter,\n        'sorting', pack_array(pack('direction', 'Descending', 'name', 'Cost'))))\n| extend TokenStatus = case(\n    Status != 'ready', Status,\n    AllResources or array_length(SelectedResources) != 1, 'Token usage requires exactly one Azure OpenAI or Foundry account. Select one AI resource; billing reports support multiple resources.',\n    ResourceType !~ 'microsoft.cognitiveservices/accounts' or ResourceKind !in~ ('OpenAI', 'AIServices'),\n        'Token metrics apply to Azure OpenAI and Foundry model-hosting accounts, not Search or ML workspaces.',\n    Start < ago(93d), 'Platform token metrics retain 93 days. Select a more recent range; older costs remain available in billing reports.',\n    End - Start > 31d, 'Token metrics support a maximum 31-day window here. Select a shorter range.',\n    'ready')\n| extend TokenResource = iff(TokenStatus == 'ready', tostring(SelectedResources[0]), '')\n| extend Export = iff(TokenStatus == 'ready', pack(\n    'resourceName', ResourceName, 'resourceGroup', ResourceGroup,\n    'resourceId', TokenResource,\n    'resourceType', ResourceType, 'resourceKind', ResourceKind, 'resourceRegion', ResourceRegion), dynamic({}))\n| project value = tostring(pack('status', Status, 'report', Report, 'tokenStatus', TokenStatus, 'tokenResource', TokenResource,\n    'body', tostring(Body), 'export', Export)), selected = true",
